  function checksView(){return '<div class="card mt-3" data-lab-check-report><div class="card-header"><h3 class="card-title">Cenários da revisão '+checks.revision+'</h3><span class="badge bg-secondary-lt ms-auto">0 envios reais</span></div><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>Cenário</th><th>Resultado</th><th>Registros sintéticos</th></tr></thead><tbody>'+checks.cases.map(c=>'<tr><td>'+esc(c.label)+'</td><td><span class="badge bg-'+(c.passed===true?'green':'red')+'-lt">'+(c.passed===true?'Conferido':'Falhou')+'</span></td><td>'+esc(c.attempts===null?'—':c.attempts)+'</td></tr>').join('')+'</tbody></table></div></div>';}
